function getColorIndiceProd(IND_PRODC) {
    switch (true) {
        case (IND_PRODC >= 0 && IND_PRODC <= 3):
            return { color: "#5A1A00" };
        case (IND_PRODC > 3 && IND_PRODC <= 9):
            return { color: "#8B2B00" };
        case (IND_PRODC > 9 && IND_PRODC <= 16):
            return { color: "#B13600" };
        case (IND_PRODC > 16 && IND_PRODC <= 23):
            return { color: "#D74600" };
        case (IND_PRODC > 23 && IND_PRODC <= 30):
            return { color: "#FF6600" };
        case (IND_PRODC > 30 && IND_PRODC <= 37):
            return { color: "#FFA500" };
        case (IND_PRODC > 37 && IND_PRODC <= 45):
            return { color: "#FFD700" };
        case (IND_PRODC > 45 && IND_PRODC <= 52):
            return { color: "#FFFF00" };
        case (IND_PRODC > 52 && IND_PRODC <= 59):
            return { color: "#D4F900" };
        case (IND_PRODC > 59 && IND_PRODC <= 66):
            return { color: "#A7F600" };
        case (IND_PRODC > 66 && IND_PRODC <= 74):
            return { color: "#5DF100" };
        case (IND_PRODC > 74 && IND_PRODC <= 85):
            return { color: "#00E100" };
        case (IND_PRODC > 85 && IND_PRODC <= 95):
            return { color: "#00C800" };
        default:
            return { color: "#000000" }; // Color por defecto en caso de que no haya coincidencia
    }
}


function styleSuelos(feature) {
    const { color } = getColorIndiceProd(feature.properties.IND_PRODC);
    return {
      color: color,
      weight: 2,
      opacity: 0.9,
      dashArray: "0",
      fillOpacity: 0.9,
    };
  }

// Contenido del popup para cada feature
function popupContentSuelos(feature) {
  return (
      "<div id='Estilo1'><h3>Descripción</h3></div>" +
      "<hr class='hrx' style='color: #ef7d26;' align='left' noshade='noshade' size='0.5' width='100%' />" +
      "<div id='Estilo3a'>" +
      "<b> Indice de Productividad : </b>" + feature.properties.IND_PRODC + "<br>" +
      "<b> Tipo de Suelo : </b>" + feature.properties.tipo_uc + "<br>" +
        "<br>" +
        "<b> Nombre de Suelo : </b>" + feature.properties.orden_sue1 + "<br>" +
        "<br>" +
      "</div>"
  );
}
// leyenda
// Función para generar la leyenda
function createLegendSuelos() {
    var legend = L.control({ position: 'bottomright' });

    legend.onAdd = function () {
        var div = L.DomUtil.create('div', 'info legend');
        var labels = [];
        var styles = [
            { label: 'Indice de Productividad', color: ' ' },
            { label: '0 - 3', color: '#5A1A00' },
            { label: '3 - 9', color: '#8B2B00' },
            { label: '9 - 16', color: '#B13600' },
            { label: '16 - 23', color: '#D74600' },
            { label: '23 - 30', color: '#FF6600' },
            { label: '30 - 37', color: '#FFA500' },
            { label: '37 - 45', color: '#FFD700' },
            { label: '45 - 52', color: '#FFFF00' },
            { label: '52 - 59', color: '#D4F900' },
            { label: '59 - 66', color: '#A7F600' },
            { label: '66 - 74', color: '#5DF100' },
            { label: '74 - 85', color: '#00E100' },
            { label: '85 - 95', color: '#00C800' }
        ];

        // Genera el contenido HTML de la leyenda
        styles.forEach(function (style) {
            labels.push(
                '<i style="background:' + style.color + '"></i> ' + style.label
            );
        });

        div.innerHTML = labels.join('<br>');
        return div;
    };

    // Función para mostrar/ocultar la leyenda
    function toggleLegend() {
        if (map.hasLayer(SuelosTipo)) {
            legend.addTo(map);
        } else {
            legend.remove();
        }
    }
// Eliminar la leyenda al inicio
legend.remove();
    // Escucha el cambio de estado de la capa
    map.on('overlayadd overlayremove', toggleLegend);
}

